import 'package:firebase_auth/firebase_auth.dart';

/// Central dictionary and translation engine for PaperTrading - Crypto & Stocks.
/// Provides instant, offline translations across English, Hindi, and Spanish.
class AppTranslations {
  static String currentLanguage = 'English';

  static void setLanguage(String lang) {
    String code = 'en';
    if (lang.toLowerCase().contains('hi')) {
      currentLanguage = 'Hindi';
      code = 'hi';
    } else if (lang.toLowerCase().contains('es') || lang.toLowerCase().contains('span')) {
      currentLanguage = 'Spanish';
      code = 'es';
    } else {
      currentLanguage = 'English';
      code = 'en';
    }
    try {
      FirebaseAuth.instance.setLanguageCode(code);
    } catch (_) {}
  }

