    "Hedera is an enterprise-grade public network using hashgraph consensus.": "Hedera हैशग्राफ सर्वसम्मति का उपयोग करने वाला एक एंटरप्राइज़-ग्रेड सार्वजनिक नेटवर्क है।",
    "Selling pressure exhausted. High probability of technical relief rally.": "बिक्री का दबाव समाप्त हो गया है। तकनीकी रिलीफ रैली की उच्च संभावना है।",
    "Shorting or going short means you expect the asset's price to decrease.": "शॉर्टिंग या शॉर्ट जाने का मतलब है कि आप संपत्ति की कीमत में कमी की उम्मीद करते हैं।",
    "Synthetix is a decentralized protocol for synthetic assets on Ethereum.": "Synthetix एथेरियम पर सिंथेटिक संपत्तियों के लिए एक विकेंद्रीकृत प्रोटोकॉल है।",
