    "No historical trades or position events found on record for this account.": "इस खाते के लिए रिकॉर्ड में कोई ऐतिहासिक ट्रेड या पोजीशन इवेंट नहीं मिले।",
    "Payments are processed by Play Billing. Your card details never reach us.": "भुगतान Play Billing द्वारा प्रोसेस किए जाते हैं। आपके कार्ड का विवरण हम तक कभी नहीं पहुंचता।",
