    "Which of these is the safest way to store large amounts of cryptocurrency?": "बड़ी मात्रा में क्रिप्टोकरेंसी को स्टोर करने का इनमें से सबसे सुरक्षित तरीका कौन सा है?",
    "Lido DAO governs the Lido liquid staking protocol for ETH and other assets.": "Lido DAO, ETH और अन्य संपत्तियों के लिए Lido लिक्विड स्टेकिंग प्रोटोकॉल को नियंत्रित करता है।",
    "TRON is a blockchain platform focused on content sharing and entertainment.": "TRON सामग्री साझाकरण और मनोरंजन पर केंद्रित एक ब्लॉकचेन प्लेटफ़ॉर्म है।",
    "Tell us what features you'd love to see and we'll prioritise the best ones.": "हमें बताएं कि आप कौन से फ़ीचर्स देखना पसंद करेंगे और हम सर्वश्रेष्ठ को प्राथमिकता देंगे।",
    "A bull market is characterized by rising prices and optimism among investors.": "बुल मार्केट की पहचान बढ़ती कीमतों और निवेशकों के बीच आशावाद से होती है।",
    "All buy and sell orders occurred at realistic, positive crypto market prices.": "सभी खरीद और बिक्री ऑर्डर यथार्थवादी, सकारात्मक क्रिप्टो बाजार मूल्यों पर हुए।",
    "All participants start at 0.0% weekly baseline. Win 1v1 duels to boost score!": "सभी प्रतिभागी 0.0% साप्ताहिक बेसलाइन से शुरुआत करते हैं। स्कोर बढ़ाने के लिए 1v1 ड्यूल जीतें!",
    "Get institutional-grade technical algorithmic trading insights on every coin:": "प्रत्येक कॉइन पर संस्थागत स्तर के तकनीकी एल्गोरिथम ट्रेडिंग इनसाइट्स प्राप्त करें:",
    "Help us keep the community safe. Why are you reporting this setup or message?": "कम्युनिटी को सुरक्षित रखने में हमारी मदद करें। आप इस सेटअप या संदेश की रिपोर्ट क्यों कर रहे हैं?",
    "Share your paper trades in the Community Feed to build your trading audience!": "अपने ट्रेडिंग दर्शकों को बढ़ाने के लिए कम्युनिटी फ़ीड में अपने पेपर ट्रेड्स साझा करें!",
    "Solana Ecosystem Expands as Decentralized Exchange Volumes Challenge Top CEXs": "सोलाना इकोसिस्टम का विस्तार, विकेंद्रीकृत एक्सचेंज वॉल्यूम शीर्ष CEX को चुनौती दे रहा है",
    "This notification will be delivered to EVERY active trader in the system:\\n\\n": "यह सूचना सिस्टम के प्रत्येक सक्रिय ट्रेडर को भेजी जाएगी:\\n\\n",
    "Too many attempts. Please wait a minute before requesting another reset link.": "अत्यधिक प्रयास। दूसरा रीसेट लिंक अनुरोध करने से पहले कृपया एक मिनट प्रतीक्षा करें।",
    "Aave is a decentralized non-custodial liquidity protocol for earning interest.": "Aave ब्याज अर्जित करने के लिए एक विकेंद्रीकृत नॉन-कस्टोडियल लिक्विडिटी प्रोटोकॉल है।",
    "NEAR Protocol is a sharded proof-of-stake blockchain designed for scalability.": "NEAR Protocol स्केलेबिलिटी के लिए डिज़ाइन किया गया एक शार्डेड प्रूफ-ऑफ-स्टेक ब्लॉकचेन है।",
    "A bear market is characterized by falling prices and pessimism among investors.": "बेयर मार्केट की पहचान गिरती कीमतों और निवेशकों के बीच निराशावाद से होती है।",
    "BNB powers the BNB Chain ecosystem and is used for transaction fees on Binance.": "BNB BNB Chain इकोसिस्टम को शक्ति प्रदान करता है और इसका उपयोग Binance पर लेनदेन शुल्क के लिए किया जाता है।",
    "Compound is an algorithmic, autonomous interest rate protocol for DeFi lending.": "Compound DeFi लेंडिंग के लिए एक एल्गोरिथम, स्वायत्त ब्याज दर प्रोटोकॉल है।",
    "Placed limit and stop-limit orders waiting for market trigger will appear here.": "मार्केट ट्रिगर की प्रतीक्षा कर रहे रखे गए लिमिट और स्टॉप-लिमिट ऑर्डर्स यहां दिखाई देंगे।",
    "Stacks is a Layer 2 for Bitcoin, enabling smart contracts and dApps on Bitcoin.": "Stacks बिटकॉइन के लिए एक लेयर 2 है, जो बिटकॉइन पर स्मार्ट अनुबंधों और dApps को सक्षम बनाता है।",
    "No account found with this email address. Please check your spelling or sign up.": "इस ईमेल पते से कोई खाता नहीं मिला। कृपया अपनी स्पेलिंग जांचें या साइन अप करें।",
    "Set up your trader identity and preferences to begin simulated market execution.": "सिम्युलेटेड मार्केट निष्पादन शुरू करने के लिए अपनी ट्रेडर पहचान और प्राथमिकताएं सेट करें।",
    "Solvency verified: User never went negative during their entire trading history.": "सॉल्वेंसी सत्यापित: उपयोगकर्ता का बैलेंस उनके पूरे ट्रेडिंग इतिहास में कभी नकारात्मक नहीं हुआ।",
    "Arbitrum is a leading Ethereum Layer 2 scaling solution using optimistic rollups.": "Arbitrum आशावादी रोलअप का उपयोग करने वाला एक अग्रणी इथेरियम लेयर 2 स्केलिंग समाधान है।",
    "Could not fetch recent price history. Please check your connection and try again.": "हालिया मूल्य इतिहास लोड नहीं हो सका। कृपया अपना कनेक्शन जांचें और पुन: प्रयास करें।",
    "Curve is a decentralized exchange optimized for stablecoin trading with low fees.": "Curve एक विकेंद्रीकृत एक्सचेंज है जो कम शुल्क के साथ स्थिर सिक्कों (stablecoins) के व्यापार के लिए अनुकूलित है।",
    "Bitcoin Cash is a fork of Bitcoin with larger block sizes for faster transactions.": "Bitcoin Cash तेज़ लेनदेन के लिए बड़े ब्लॉक आकार वाला बिटकॉइन का एक फोर्क है।",
    "Bonk is the first dog-themed social utility token launched on the Solana ecosystem.": "Bonk सोलाना इकोसिस्टम पर लॉन्च किया गया पहला डॉग-थीम वाला सोशल यूटिलिटी टोकन है।",
    "Market candle data is slow to respond or unavailable. Please check your connection.": "मार्केट कैंडल डेटा धीमी प्रतिक्रिया दे रहा है या अनुपलब्ध है। कृपया अपना कनेक्शन जांचें।",
    "Check in daily in the Rewards tab to maintain your streak flame and climb the ranks!": "अपनी स्ट्रीक ज्वाला बनाए रखने और रैंक बढ़ाने के लिए रिवॉर्ड्स टैब में दैनिक चेक-इन करें!",
    "Ethereum Classic is the original, immutable proof-of-work smart contract blockchain.": "Ethereum Classic मूल, अपरिवर्तनीय प्रूफ-ऑफ-वर्क स्मार्ट कॉन्ट्रैक्ट ब्लॉकचेन है।",
    "Maintain daily check-in habits. Complete Day 7 to unlock the legendary streak vault.": "दैनिक चेक-इन की आदत बनाए रखें। लीजेंडरी स्ट्रीक वॉल्ट अनलॉक करने के लिए दिन 7 पूरा करें।",
    "No fingerprints or face enrolled on device. Please register one in Android Settings.": "डिवाइस पर कोई फ़िंगरप्रिंट या चेहरा पंजीकृत नहीं है। कृपया एंड्रॉइड सेटिंग्स में जाकर पंजीकृत करें।",
    "Please log out and log back in to verify your identity before deleting your account.": "अपना खाता हटाने से पहले कृपया अपनी पहचान सत्यापित करने के लिए लॉग आउट करें और फिर से लॉग इन करें।",
    "Zero-margin futures exploit: Opened high-leverage position without margin deduction.": "शून्य-मार्जिन फ्यूचर्स एक्सप्लॉइट: बिना मार्जिन कटौती के उच्च-लीवरेज पोजीशन खोली गई।",
    "BOOK OF MEME is an experimental Web3 meme creation and decentralized storage project.": "BOOK OF MEME एक प्रयोगात्मक Web3 मीम निर्माण और विकेंद्रीकृत स्टोरेज प्रोजेक्ट है।",
    "Decentraland is a virtual world where users can buy, sell, and build on virtual land.": "Decentraland एक आभासी दुनिया है जहाँ उपयोगकर्ता आभासी ज़मीन खरीद, बेच और बना सकते हैं।",
    "Password must be at least 8 characters and include uppercase, lowercase, and numbers.": "पासवर्ड कम से कम 8 वर्णों का होना चाहिए और इसमें बड़े अक्षर, छोटे अक्षर और संख्याएं शामिल होनी चाहिए।",
    "ROI measures the profitability of an investment as a percentage of the original cost.": "ROI मूल लागत के प्रतिशत के रूप में निवेश की लाभप्रदता को मापता है।",
    "User cash balance remained solvent throughout all sequential trades and transactions.": "सभी लगातार ट्रेड्स और लेन-देन में उपयोगकर्ता का नकद बैलेंस शोधनक्षम रहा।",
    "Broadcast instant notifications to all active paper traders or target a specific user.": "सभी सक्रिय पेपर ट्रेडर्स को तुरंत सूचनाएं भेजें या किसी विशिष्ट उपयोगकर्ता को लक्षित करें।",
    "Sui is a Layer 1 blockchain and smart contract platform designed for instant finality.": "Sui एक लेयर 1 ब्लॉकचेन और स्मार्ट अनुबंध प्लेटफ़ॉर्म है जिसे तत्काल अंतिमता के लिए डिज़ाइन किया गया है।",
    "XRP is the native asset of the XRP Ledger, used for fast and low-cost global payments.": "XRP एक्सआरपी लेजर की मूल संपत्ति है, जिसका उपयोग तेज़ और कम लागत वाले वैश्विक भुगतानों के लिए किया जाता है।",
    "Bitcoin is the first decentralized cryptocurrency, created by Satoshi Nakamoto in 2009.": "बिटकॉइन पहली विकेंद्रीकृत क्रिप्टोकरेंसी है, जिसे 2009 में सातोशी नाकामोटो द्वारा बनाया गया था।",
    "Cardano is a proof-of-stake blockchain platform focused on security and sustainability.": "Cardano सुरक्षा और स्थिरता पर केंद्रित एक प्रूफ-ऑफ-स्टेक ब्लॉकचेन प्लेटफ़ॉर्म है।",
    "Maker is the governance token of the MakerDAO protocol, which issues the DAI stablecoin.": "Maker MakerDAO प्रोटोकॉल का गवर्नेंस टोकन है, जो DAI स्टेबलकॉइन जारी करता है।",
    "Chainlink is a decentralized oracle network providing real-world data to smart contracts.": "Chainlink एक विकेंद्रीकृत ऑरेकल नेटवर्क है जो स्मार्ट अनुबंधों को वास्तविक दुनिया का डेटा प्रदान करता है।",
    "Every coin held in the portfolio matches historical buy orders minus sell orders exactly.": "पोर्टफोलियो में रखी गई प्रत्येक कॉइन ऐतिहासिक खरीद ऑर्डर माइनस बिक्री ऑर्डर से बिल्कुल मेल खाती है।",
    "Solana is a high-performance blockchain supporting fast, low-cost transactions and dApps.": "Solana एक उच्च-प्रदर्शन ब्लॉकचेन है जो तेज़, कम लागत वाले लेनदेन और dApps का समर्थन करता है।",
    "Add funds to your paper trading account to practice new strategies without financial risk.": "वित्तीय जोखिम के बिना नई रणनीतियों का अभ्यास करने के लिए अपने पेपर ट्रेडिंग खाते में फंड जोड़ें।",
    "Aptos is a Layer 1 blockchain built on Move language, focused on safety and upgradability.": "Aptos Move भाषा पर निर्मित एक लेयर 1 ब्लॉकचेन है, जो सुरक्षा और अपग्रेडेबिलिटी पर केंद्रित है।",
    "Reconciling ledger, auditing holdings vs trade history, verifying 100x leverage margins...": "लेज़र का मिलान, ट्रेड इतिहास बनाम होल्डिंग्स का ऑडिट, 100x लीवरेज मार्जिन का सत्यापन किया जा रहा है...",
    "XP tracks your real-time trading experience across Spot, Futures Pro, and 1v1 Blitz duels.": "XP स्पॉट, फ्यूचर्स प्रो और 1v1 ब्लिट्ज़ ड्यूल्स में आपके रीयल-टाइम ट्रेडिंग अनुभव को ट्रैक करता है।",
    "Your available cash is empty. Watch a short video to claim an instant free capital refill.": "आपका उपलब्ध नकद समाप्त हो गया है। तत्काल मुफ़्त पूंजी रीफ़िल का दावा करने के लिए एक छोटा वीडियो देखें।",
    "Dogecoin started as a meme but grew into one of the largest cryptocurrencies by market cap.": "Dogecoin एक मीम के रूप में शुरू हुआ लेकिन मार्केट कैप के हिसाब से सबसे बड़ी क्रिप्टोकरेंसी में से एक बन गया।",
    "Enter the email associated with your account and we will send you a password recovery link.": "अपने खाते से जुड़ा ईमेल दर्ज करें और हम आपको पासवर्ड रिकवरी लिंक भेजेंगे।",
    "Jito is a liquid staking protocol and MEV infrastructure platform for the Solana ecosystem.": "Jito सोलाना पारिस्थितिकी तंत्र के लिए एक लिक्विड स्टेकिंग प्रोटोकॉल और MEV बुनियादी ढांचा मंच है।",
    "Zombie position exploit: Active position breached liquidation price but was not liquidated.": "ज़ोंबी पोजीशन एक्सप्लॉइट: सक्रिय पोजीशन लिक्विडेशन मूल्य से आगे निकल गई लेकिन लिक्विडेट नहीं की गई।",
    "dogwifhat is a popular decentralized community meme coin launched on the Solana blockchain.": "dogwifhat सोलाना ब्लॉकचेन पर लॉन्च किया गया एक लोकप्रिय विकेंद्रीकृत कम्युनिटी मेम कॉइन है।",
    "Filecoin is a decentralized storage network to store the world's most important information.": "Filecoin दुनिया की सबसे महत्वपूर्ण जानकारी को संग्रहीत करने के लिए एक विकेंद्रीकृत भंडारण नेटवर्क है।",
    "Notcoin is a viral Web3 tap-to-earn game and community token launched on the TON blockchain.": "Notcoin TON ब्लॉकचेन पर लॉन्च किया गया एक वायरल Web3 टैप-टू-अर्न गेम और कम्युनिटी टोकन है।",
    "Note: Please attach any screenshots or images directly to this email to help us investigate.": "नोट: जांच में हमारी सहायता के लिए कृपया किसी भी स्क्रीनशॉट या चित्र को सीधे इस ईमेल से संलग्न करें।",
    "Notice: Your 10-day appeal window has expired. Permanent account deletion is being executed.": "सूचना: आपकी 10-दिवसीय अपील अवधि समाप्त हो गई है। स्थायी खाता निष्कासन निष्पादित किया जा रहा है।",
    "Pepe is a deflationary memecoin launched on Ethereum as a tribute to the Pepe the Frog meme.": "Pepe एक अपस्फीतिकारी मीमकॉइन है जिसे पेपे द फ्रॉग मीम के सम्मान में एथेरियम पर लॉन्च किया गया है।",
    "Pyth Network is a high-frequency financial oracle network delivering sub-second market data.": "Pyth Network एक हाई-फ़्रीक्वेंसी वित्तीय ओरेकल नेटवर्क है जो सब-सेकंड मार्केट डेटा प्रदान करता है।",
    "Are you sure you want to permanently delete this top-up record? This action cannot be undone.": "क्या आप वाकई इस टॉप-अप रिकॉर्ड को स्थायी रूप से हटाना चाहते हैं? यह क्रिया पूर्ववत नहीं की जा सकती।",
    "ZKsync is a Layer 2 scaling protocol using zero-knowledge rollups to scale Ethereum securely.": "ZKsync एथेरियम को सुरक्षित रूप से स्केल करने के लिए जीरो-नॉलेज रोलअप का उपयोग करने वाला एक लेयर 2 स्केलिंग प्रोटोकॉल है।",
    "A wallet address is like a bank account number that others can use to send you cryptocurrency.": "वॉलेट एड्रेस एक बैंक खाता संख्या की तरह है जिसका उपयोग अन्य लोग आपको क्रिप्टोकरेंसी भेजने के लिए कर सकते हैं।",
    "Their posts and comments will no longer appear in your feed. You can unblock them at any time.": "उनकी पोस्ट और टिप्पणियां अब आपकी फ़ीड में दिखाई नहीं देंगी। आप उन्हें किसी भी समय अनब्लॉक कर सकते हैं।",
    "Welcome to the new trading season! Compete in the Weekly Championship for virtual cash prizes.": "नए ट्रेडिंग सीज़न में आपका स्वागत है! वर्चुअल नकद पुरस्कारों के लिए साप्ताहिक चैंपियनशिप में भाग लें।",
    "Could not connect to your account profile. Please check your internet connection and try again.": "आपके खाता प्रोफ़ाइल से कनेक्ट नहीं हो सका। कृपया अपना इंटरनेट कनेक्शन जांचें और पुन: प्रयास करें।",
    "Describe the feature in detail. The more context you give, the easier it is for us to build it.": "फ़ीचर का विस्तार से वर्णन करें। आप जितना अधिक संदर्भ देंगे, हमारे लिए इसे बनाना उतना ही आसान होगा।",
    "Ethereum is a decentralized platform for smart contracts and dApps, created by Vitalik Buterin.": "Ethereum स्मार्ट कॉन्ट्रैक्ट्स और dApps के लिए एक विकेंद्रीकृत प्लेटफ़ॉर्म है, जिसे विटालिक ब्यूटिरिन द्वारा बनाया गया है।",
    "Avalanche is a smart contract platform designed for DeFi with near-instant transaction finality.": "Avalanche लगभग तात्कालिक लेनदेन अंतिमता के साथ DeFi के लिए डिज़ाइन किया गया एक स्मार्ट अनुबंध प्लेटफ़ॉर्म है।",
    "Enable a 4-digit PIN and Biometric Lock to keep your virtual trading portfolio and stats secure.": "अपने वर्चुअल ट्रेडिंग पोर्टफोलियो और आंकड़ों को सुरक्षित रखने के लिए 4-अंकीय पिन और बायोमेट्रिक लॉक सक्षम करें।",
    "Ban this user account or apply an administrative reset to protect the competition and leaderboard.": "प्रतियोगिता और लीडरबोर्ड की सुरक्षा के लिए इस उपयोगकर्ता खाते को बैन करें या प्रशासनिक रीसेट लागू करें।",
    "Current market price has breached the position liquidation threshold, but position remains active.": "वर्तमान बाजार मूल्य ने पोजीशन लिक्विडेशन सीमा का उल्लंघन किया है, लेकिन पोजीशन सक्रिय बनी हुई है।",
    "Inspect ideas, feature suggestions, and UX improvements submitted by traders across the community.": "समुदाय भर के ट्रेडर्स द्वारा सबमिट किए गए विचारों, सुविधा सुझावों और UX सुधारों का निरीक्षण करें।",
    "Stellar is an open blockchain network connecting financial institutions for low-cost transactions.": "Stellar कम लागत वाले लेन-देन के लिए वित्तीय संस्थानों को जोड़ने वाला एक खुला ब्लॉकचेन नेटवर्क है।",
    "Account verification is taking longer than expected. Please check your network or proceed to login.": "खाता सत्यापन में अपेक्षा से अधिक समय लग रहा है। कृपया अपना नेटवर्क जांचें या लॉगिन करने के लिए आगे बढ़ें।",
    "Verifying all spot trades, futures margin deductions,\\ncoin inventory, and ledger reconciliation...": "सभी स्पॉट ट्रेड्स, फ्यूचर्स मार्जिन कटौती,\\nकॉइन इन्वेंट्री और लेज़र मिलान का सत्यापन किया जा रहा है...",
    "A limit order guarantees the price but not the execution, as the market must reach your limit price.": "एक लिमिट ऑर्डर कीमत की गारंटी देता है लेकिन निष्पादन की नहीं, क्योंकि बाजार को आपकी लिमिट कीमत तक पहुंचना आवश्यक है।",
    "Arkham is an AI-powered blockchain analysis and intelligence platform revealing transaction origins.": "Arkham एक AI-संचालित ब्लॉकचेन विश्लेषण और इंटेलिजेंस प्लेटफ़ॉर्म है जो लेनदेन की उत्पत्ति को प्रकट करता है।",
    "Celestia is a modular blockchain network that rethinks data availability and consensus architecture.": "Celestia एक मॉड्यूलर ब्लॉकचेन नेटवर्क है जो डेटा उपलब्धता और आम सहमति आर्किटेक्चर पर पुनर्विचार करता है।",
    "Fantom is a highly scalable blockchain platform for DeFi, crypto dApps, and enterprise applications.": "Fantom DeFi, क्रिप्टो dApps और एंटरप्राइज़ अनुप्रयोगों के लिए एक अत्यधिक स्केलेबल ब्लॉकचेन प्लेटफ़ॉर्म है।",
    "Illegal leverage detected: User has futures positions with leverage exceeding the 100x platform cap.": "अवैध लीवरेज का पता चला: उपयोगकर्ता के पास 100x प्लेटफ़ॉर्म सीमा से अधिक लीवरेज वाली फ्यूचर्स पोजीशन हैं।",
    "Cross-checks every coin in the user portfolio against their historical buy and sell trades. Flags any": "उपयोगकर्ता पोर्टफोलियो के प्रत्येक कॉइन को उनके ऐतिहासिक खरीद और बिक्री ट्रेडों के विरुद्ध क्रॉस-चेक करता है। किसी भी गड़बड़ी को फ़्लैग करता है",
    "Explore markets, test your trading strategies with zero risk, and compete in the Weekly Championship!": "बाज़ारों को एक्सप्लोर करें, शून्य जोखिम के साथ अपनी ट्रेडिंग रणनीतियों का परीक्षण करें, और साप्ताहिक चैम्पियनशिप में प्रतिस्पर्धा करें!",
    "From trade fills and liquidation alerts to weekly championship prizes, your alerts will show up here.": "ट्रेड निष्पादन और लिक्विडेशन अलर्ट से लेकर साप्ताहिक चैंपियनशिप पुरस्कारों तक, आपके अलर्ट यहां दिखाई देंगे।",
    "Going long means you are buying a contract with the expectation that the asset's price will increase.": "लॉन्ग पोजीशन लेने का अर्थ है कि आप इस उम्मीद के साथ एक कॉन्ट्रैक्ट खरीद रहे हैं कि परिसंपत्ति की कीमत बढ़ेगी।",
    "Pendle is a permissionless yield-trading protocol enabling tokenization and trading of future yields.": "Pendle एक अनुमति-रहित यील्ड-ट्रेडिंग प्रोटोकॉल है जो भविष्य की यील्ड के टोकनाइज़ेशन और ट्रेडिंग को सक्षम बनाता है।",
    "Review trade and wallet history manually. Ban is NOT recommended unless suspicious patterns escalate.": "ट्रेड और वॉलेट इतिहास की मैन्युअल रूप से समीक्षा करें। जब तक संदिग्ध पैटर्न न बढ़ें, बैन की अनुशंसा नहीं की जाती है।",
    "Watch a short video to receive an instant free capital refill and jump straight back into the market.": "तुरंत मुफ़्त पूंजी रीफ़िल प्राप्त करने और बाज़ार में वापस आने के लिए एक छोटा वीडियो देखें।",
    "Hardware wallets keep your private keys offline, protecting your assets from online hacks and malware.": "हार्डवेयर वॉलेट आपकी प्राइवेट की को ऑफ़लाइन रखते हैं, जिससे आपकी संपत्तियों को ऑनलाइन हैक और मैलवेयर से बचाया जा सकता है।",
    "Toncoin is the decentralized Layer 1 blockchain developed by Telegram for scalable micro-transactions.": "Toncoin स्केलेबल माइक्रो-ट्रांजैक्शन के लिए टेलीग्राम द्वारा विकसित विकेंद्रीकृत लेयर 1 ब्लॉकचेन है।",
    "VeChain is an enterprise blockchain platform enhancing supply chain management and business processes.": "VeChain आपूर्ति श्रृंखला प्रबंधन और व्यावसायिक प्रक्रियाओं को बेहतर बनाने वाला एक एंटरप्राइज ब्लॉकचेन प्लेटफ़ॉर्म है।",
    "io.net is a decentralized physical infrastructure network providing on-demand distributed GPU compute.": "io.net एक विकेंद्रीकृत भौतिक अवसंरचना नेटवर्क है जो ऑन-डिमांड वितरित GPU कंप्यूट प्रदान करता है।",
    "• 1v1 Blitz Arena Boost: Every blitz arena win awards +5.0% score directly to your championship tally.": "• 1v1 ब्लिट्ज़ एरिना बूस्ट: प्रत्येक ब्लिट्ज़ एरिना जीत आपकी चैम्पियनशिप टैली में सीधे +5.0% स्कोर जोड़ती है।",
    "A stop-loss order helps manage risk by automatically closing a position if the price moves against you.": "एक स्टॉप-लॉस ऑर्डर पोजीशन को स्वचालित रूप से बंद करके जोखिम प्रबंधित करने में मदद करता है यदि कीमत आपके प्रतिकूल जाती है।",
    "Chiliz powers Socios.com, enabling fans to purchase Fan Tokens for top football clubs and sports teams.": "Chiliz Socios.com को संचालित करता है, जिससे प्रशंसक शीर्ष फुटबॉल क्लबों और खेल टीमों के लिए फैन टोकन खरीद सकते हैं।",
    "Ethena is a synthetic dollar protocol built on Ethereum that provides crypto-native yield through USDe.": "Ethena एथेरियम पर निर्मित एक सिंथेटिक डॉलर प्रोटोकॉल है जो USDe के माध्यम से क्रिप्टो-मूल उपज प्रदान करता है।",
    "1. User executed orders exceeding available virtual cash, plunging balance into deep negative overdraft.": "1. उपयोगकर्ता ने उपलब्ध वर्चुअल कैश से अधिक के ऑर्डर निष्पादित किए, जिससे बैलेंस अत्यधिक नकारात्मक ओवरड्राफ्ट में चला गया।",
    "Algorand is a self-sustaining, decentralized blockchain network supporting a wide range of applications.": "Algorand एक आत्मनिर्भर, विकेंद्रीकृत ब्लॉकचेन नेटवर्क है जो अनुप्रयोगों की एक विस्तृत श्रृंखला का समर्थन करता है।",
    "Market structure is bullish. Enter on minor dips towards support with targets set at recent swing highs.": "मार्केट स्ट्रक्चर बुलिश है। हालिया स्विंग हाई पर लक्ष्य रखकर सपोर्ट की ओर हल्की गिरावट पर प्रवेश करें।",
    "Price is consolidating in a neutral band. Wait for a definitive breakout above resistance before buying.": "कीमत एक तटस्थ दायरे में समेकित (कंसोलिडेट) हो रही है। खरीदने से पहले रेजिस्टेंस से ऊपर एक निर्णायक ब्रेकआउट की प्रतीक्षा करें।",
    "Upward momentum waning near resistance. Consider trimming profits or placing tight trailing stop-losses.": "रेजिस्टेंस के पास ऊपर की गति कम हो रही है। मुनाफ़ा बुक करने या सख्त ट्रेलिंग स्टॉप-लॉस लगाने पर विचार करें।",
    "Sei is the fastest Layer 1 blockchain, specialized for trading and decentralized exchange infrastructure.": "Sei सबसे तेज़ लेयर 1 ब्लॉकचेन है, जो ट्रेडिंग और विकेंद्रीकृत एक्सचेंज इंफ्रास्ट्रक्चर के लिए विशेष रूप से अनुकूलित है।",
    "Track real monetary revenue, Google Play purchase tokens, approval statuses, and user payment timestamps.": "वास्तविक मौद्रिक राजस्व, Google Play खरीदारी टोकन, स्वीकृति स्थिति और उपयोगकर्ता भुगतान समय-चिह्न ट्रैक करें।",
    "Welcome to the new trading season! Enjoy smoother charts, upgraded indicators, and enhanced server speed.": "नए ट्रेडिंग सीज़न में आपका स्वागत है! अधिक स्मूथ चार्ट, उन्नत संकेतक और बेहतर सर्वर गति का आनंद लें।",
    "1. User virtual balance was directly altered in Firestore without matching trade profits or daily rewards.": "1. उपयोगकर्ता का वर्चुअल बैलेंस बिना किसी ट्रेड प्रॉफिट या दैनिक पुरस्कारों के सीधे Firestore में बदल दिया गया था।",
    "• Weekly Fresh Start: Leaderboard scores reset to 0.0% every week so all traders compete on equal footing.": "• साप्ताहिक नई शुरुआत: लीडरबोर्ड स्कोर हर हफ्ते 0.0% पर रीसेट होते हैं ताकि सभी ट्रेडर समान स्तर पर प्रतिस्पर्धा कर सकें।",
    "Market Cap is calculated by multiplying the current price of a single coin by its total circulating supply.": "मार्केट कैप की गणना किसी कॉइन के मौजूदा मूल्य को उसकी कुल सर्कुलेटिंग सप्लाई से गुणा करके की जाती है।",
    "Starknet is a Permissionless Validity-Rollup Layer 2 for Ethereum scaling using STARK cryptographic proofs.": "Starknet STARK क्रिप्टोग्राफ़िक प्रमाणों का उपयोग करके एथेरियम स्केलिंग के लिए एक अनुमतिहीन वैलिडिटी-रोलअप लेयर 2 है।",
    "All winners receive an in-app claim popup. Tournament scores will be safely reset to 0.0% for the next week.": "सभी विजेताओं को इन-ऐप क्लेम पॉपअप प्राप्त होगा। टूर्नामेंट स्कोर अगले सप्ताह के लिए 0.0% पर सुरक्षित रूप से रीसेट हो जाएगा।",
    "GMX is a decentralized spot and perpetual exchange that supports low swap fees and zero price impact trades.": "GMX एक विकेंद्रीकृत स्पॉट और परपेचुअल एक्सचेंज है जो कम स्वैप शुल्क और शून्य मूल्य प्रभाव वाले ट्रेडों का समर्थन करता है।",
    "Severe bearish pressure and moving average breakdown. Recommended to sell spot holdings or preserve capital.": "भारी मंदी का दबाव और मूविंग एवरेज ब्रेकडाउन। स्पॉट होल्डिंग्स बेचने या पूंजी सुरक्षित रखने की सिफारिश की जाती है।",
    "Crypto never sleeps! Trade the weekend volatility with up to 20x leverage on BTC, ETH, and trending altcoins.": "क्रिप्टो कभी सोता नहीं है! BTC, ETH और ट्रेंडिंग ऑल्टकॉइन्स पर 20x तक लीवरेज के साथ सप्ताहांत की अस्थिरता का ट्रेड करें।",
    "Standard volatility range. 10x leverage offers disciplined growth with an approximate 10% liquidation buffer.": "मानक उतार-चढ़ाव सीमा। 10x लीवरेज लगभग 10% लिक्विडेशन बफ़र के साथ अनुशासित वृद्धि प्रदान करता है।",
    "The AI Signals Desk just published fresh Spot & Futures recommendations with clear Entry, TP, and SL targets.": "AI सिग्नल्स डेस्क ने स्पष्ट एंट्री, TP और SL लक्ष्यों के साथ नई स्पॉट और फ्यूचर्स सिफारिशें प्रकाशित की हैं।",
    "You will no longer see posts or comments from this trader on your timeline. You can unblock them at any time.": "अब आप अपनी टाइमलाइन पर इस ट्रेडर की पोस्ट या टिप्पणियां नहीं देख पाएंगे। आप उन्हें किसी भी समय अनब्लॉक कर सकते हैं।",
    "Unlock PaperTrading instantly using your Fingerprint or Face ID instead of typing your 4-digit PIN every time.": "हर बार अपना 4-अंकीय पिन दर्ज करने के बजाय फिंगरप्रिंट या फेस आईडी का उपयोग करके PaperTrading को तुरंत अनलॉक करें।",
    "Welcome to the Ultimate Crypto Trading Simulator! Here is a breakdown of all the features and how to use them.": "अल्टीमेट क्रिप्टो ट्रेडिंग सिमुलेटर में आपका स्वागत है! यहाँ सभी सुविधाओं और उनके उपयोग का विवरण दिया गया है।",
    "Auto-Payout Active: Every Monday at 12:00 AM midnight, top 10 traders are credited and tournament scores reset.": "ऑटो-पेआउट सक्रिय: प्रत्येक सोमवार आधी रात 12:00 AM पर, शीर्ष 10 ट्रेडर्स को क्रेडिट दिया जाता है और टूर्नामेंट स्कोर रीसेट हो जाते हैं।",
    "Traders are waiting in the Arena! Put your trading skills to the test in 60-second live blitz duels to earn XP.": "ट्रेडर्स एरिना में प्रतीक्षा कर रहे हैं! XP अर्जित करने के लिए 60-सेकंड के लाइव ब्लिट्ज ड्यूल में अपने ट्रेडिंग कौशल का परीक्षण करें।",
    "1. User injected or synced coin holdings directly without corresponding buy trade transactions in trade history.": "1. उपयोगकर्ता ने ट्रेड इतिहास में संबंधित खरीद ट्रेड लेनदेन के बिना सीधे कॉइन होल्डिंग्स को इंजेक्ट या सिंक किया।",
    "Your daily activity reward has been unlocked! Check in now to maintain your streak and claim bonus virtual cash.": "आपका दैनिक गतिविधि इनाम अनलॉक हो गया है! अपनी स्ट्रीक बनाए रखने और बोनस वर्चुअल नकद प्राप्त करने के लिए अभी चेक इन करें।",
    "Your honest review helps other paper traders discover the app and supports our continuous simulator improvements.": "आपकी ईमानदार समीक्षा अन्य पेपर ट्रेडर्स को ऐप खोजने में मदद करती है और हमारे निरंतर सिमुलेटर सुधारों का समर्थन करती है।",
    "Moderate price swings. 5x leverage offers balanced amplification while keeping liquidation at a safe 20% distance.": "मध्यम मूल्य उतार-चढ़ाव। 5x लीवरेज लिक्विडेशन को सुरक्षित 20% की दूरी पर रखते हुए संतुलित बढ़त प्रदान करता है।",
    "Ondo Finance is an institutional-grade protocol bridging traditional finance with decentralized blockchain assets.": "Ondo Finance एक संस्थागत स्तर का प्रोटोकॉल है जो पारंपरिक वित्त को विकेंद्रीकृत ब्लॉकचेन संपत्तियों से जोड़ता है।",
    "Only a few hours left today! Claim your daily reward to multiply your virtual cash bonus and unlock streak badges.": "आज केवल कुछ ही घंटे बचे हैं! अपने वर्चुअल कैश बोनस को बढ़ाने और स्ट्रीक बैज अनलॉक करने के लिए अपने दैनिक इनाम का दावा करें।",
    "Bonus virtual cash has been credited to active traders! Test out fresh Spot and Futures strategies risk-free today.": "सक्रिय ट्रेडर्स को बोनस वर्चुअल कैश क्रेडिट किया गया है! आज ही जोखिम-मुक्त नई स्पॉट और फ्यूचर्स रणनीतियों का परीक्षण करें।",
    "Internet Computer is a blockchain network that enables developers to build and host decentralized web applications.": "Internet Computer एक ब्लॉकचेन नेटवर्क है जो डेवलपर्स को विकेंद्रीकृत वेब अनुप्रयोग बनाने और होस्ट करने में सक्षम बनाता है।",
    "The weekly leaderboard finalizes at Sunday midnight! Enter high-conviction trades now to lock in your Top 10 prize.": "साप्ताहिक लीडरबोर्ड रविवार आधी रात को समाप्त होता है! अपने शीर्ष 10 पुरस्कार को सुरक्षित करने के लिए अभी उच्च-विश्वास वाले ट्रेड दर्ज करें।",
    "Your trading account has been suspended by an administrator for violating community or trading platform guidelines.": "कम्युनिटी या ट्रेडिंग प्लेटफ़ॉर्म दिशानिर्देशों का उल्लंघन करने के कारण प्रशासक द्वारा आपका ट्रेडिंग खाता निलंबित कर दिया गया है।",
    "Daily rewards, check-ins, and quest milestones were claimed with proper intervals and legitimate streak progression.": "दैनिक इनाम, चेक-इन और खोज मील के पत्थर उचित अंतराल और वैध स्ट्रीक प्रगति के साथ क्लेम किए गए थे।",
    "No ad available right now. Google AdMob is currently warming up ad inventory for this app. Please try again shortly.": "अभी कोई विज्ञापन उपलब्ध नहीं है। Google AdMob वर्तमान में इस ऐप के लिए विज्ञापन इन्वेंट्री तैयार कर रहा है। कृपया कुछ देर बाद पुनः प्रयास करें।",
    "Qualification Rule: Must cross >0.0% profit to receive prize money. 0.0% or negative scores are strictly ineligible.": "योग्यता नियम: पुरस्कार राशि प्राप्त करने के लिए >0.0% लाभ पार करना अनिवार्य है। 0.0% या नकारात्मक स्कोर पूरी तरह से अयोग्य हैं।",
    "Account displays minor numerical drift or rounding variance, but no definitive proof of cheating or bug exploitation.": "खाते में मामूली संख्यात्मक अंतर या राउंडिंग भिन्नता दिखाई देती है, लेकिन धोखाधड़ी या बग शोषण का कोई निर्णायक प्रमाण नहीं है।",
    "Crypto markets are experiencing high volume and breakout momentum. Review your open positions and manage stop-losses.": "क्रिप्टो बाजारों में उच्च वॉल्यूम और ब्रेकआउट गति का अनुभव हो रहा है। अपनी खुली पोजीशन की समीक्षा करें और स्टॉप-लॉस प्रबंधित करें।",
    "Search any trader by UID to inspect their live spot portfolio, open futures leverage, and suspicious trading volumes.": "किसी भी ट्रेडर के लाइव स्पॉट पोर्टफोलियो, ओपन फ्यूचर्स लीवरेज और संदिग्ध ट्रेडिंग वॉल्यूम की जांच के लिए यूआईडी द्वारा खोजें।",
    "Interactive TradingView WebView is supported on Android, iOS & macOS.\\nSwitch to native chart view for other platforms.": "इंटरैक्टिव TradingView WebView Android, iOS और macOS पर समर्थित है।\\nअन्य प्लेटफ़ॉर्म के लिए मूल चार्ट व्यू पर स्विच करें।",
    "Leverage lets you trade with more money than you actually have, amplifying both potential profits and potential losses.": "लीवरेज आपको वास्तव में आपके पास मौजूद पैसे से अधिक पैसे के साथ ट्रेड करने की अनुमति देता है, जिससे संभावित लाभ और संभावित नुकसान दोनों बढ़ जाते हैं।",
    "Limited time flash deal! Top up your virtual account today and receive up to 50% extra bonus capital for paper trading.": "सीमित समय की फ्लैश डील! आज ही अपना वर्चुअल खाता टॉप अप करें और पेपर ट्रेडिंग के लिए 50% तक अतिरिक्त बोनस पूंजी प्राप्त करें।",
    "A new version of Acadrio Trade is available on Google Play Store. Update now for new features and performance improvements!": "Google Play Store पर Acadrio Trade का एक नया संस्करण उपलब्ध है। नई सुविधाओं और प्रदर्शन सुधारों के लिए अभी अपडेट करें!",
    "Search by Public UID (PT-XXXXXX), Firebase UID, or Email\\nto view real-time holdings, futures positions, and recent trades.": "रीयल-टाइम होल्डिंग्स, फ्यूचर्स पोजीशन्स और हालिया ट्रेड्स देखने के लिए पब्लिक यूआईडी (PT-XXXXXX), फायरबेस यूआईडी या ईमेल द्वारा खोजें।",
    "• Zero Real-Money Risk: Prizes are virtual paper trading capital credited to your account for risk-free strategy execution.": "• शून्य वास्तविक-पैसे का जोखिम: पुरस्कार वर्चुअल पेपर ट्रेडिंग पूंजी हैं जो जोखिम-मुक्त रणनीति निष्पादन के लिए आपके खाते में जमा की जाती हैं।",
    "Weekly Leaderboard settled! Top 3 traders have received their virtual capital prizes directly to their paper trading wallet.": "साप्ताहिक लीडरबोर्ड तय हो गया! शीर्ष 3 ट्रेडर्स को उनके पेपर ट्रेडिंग वॉलेट में सीधे वर्चुअल पूंजी पुरस्कार प्राप्त हुए हैं।",
    "No ad inventory available right now. Google AdMob is currently warming up ad inventory for this app. Please try again shortly.": "अभी कोई विज्ञापन इन्वेंट्री उपलब्ध नहीं है। Google AdMob वर्तमान में इस ऐप के लिए विज्ञापन इन्वेंट्री तैयार कर रहा है। कृपया कुछ देर बाद पुनः प्रयास करें।",
    "Congratulations to the Top 10 traders! Cash awards have been credited. All players are reset to 0.0% baseline for the new week.": "शीर्ष 10 ट्रेडर्स को बधाई! नकद पुरस्कार क्रेडिट कर दिए गए हैं। नए सप्ताह के लिए सभी खिलाड़ियों को 0.0% बेसलाइन पर रीसेट कर दिया गया है।",
    "If you believe this suspension is a mistake or wish to appeal, you can submit an appeal directly via email to our support team.": "यदि आपको लगता है कि यह निलंबन एक गलती है या आप अपील करना चाहते हैं, तो आप सीधे ईमेल द्वारा हमारी सहायता टीम को एक अपील भेज सकते हैं।",
    "PaperTrading - Crypto & Stocks is strictly an educational tool. We do not handle real deposits, fiat currencies, or real crypto assets.": "पेपर ट्रेडिंग - क्रिप्टो पूरी तरह से एक शैक्षिक उपकरण है। हम वास्तविक जमा, फिएट मुद्राओं, या वास्तविक क्रिप्टो संपत्तियों का प्रबंधन नहीं करते हैं।",
    "3. User closed the position against real-time market prices, realizing immediate unearned windfall profits into virtual balance.": "3. उपयोगकर्ता ने वास्तविक समय के बाजार मूल्यों पर पोजीशन बंद कर दी, जिससे वर्चुअल बैलेंस में तत्काल अनुचित अप्रत्याशित लाभ हुआ।",
    "Every trade, coin purchase, futures position, and wallet credit reconciles mathematically with 100% precision. Account is clean.": "प्रत्येक ट्रेड, कॉइन खरीद, फ्यूचर्स पोजीशन और वॉलेट क्रेडिट गणितीय रूप से 100% सटीकता के साथ मेल खाता है। खाता साफ़ है।",
    "This will sign you out of PaperTrading and reset your local device PIN. You can log back in with your account credentials anytime.": "यह आपको PaperTrading से साइन आउट कर देगा और आपके स्थानीय डिवाइस पिन को रीसेट कर देगा। आप कभी भी अपने खाते के क्रेडेंशियल्स के साथ वापस लॉग इन कर सकते हैं।",
    "Audit every past signal triggered by the Sentinel algorithm. Review win rates, risk-to-reward metrics, and exact target hit history.": "सेंटिनल एल्गोरिदम द्वारा ट्रिगर किए गए प्रत्येक पिछले सिग्नल का ऑडिट करें। जीत दर, जोखिम-इनाम अनुपात और सटीक लक्ष्य हिट इतिहास की समीक्षा करें।",
    "On-chain analytics reveal steady institutional accumulation across major spot ETFs as network hash rate reaches fresh all-time highs.": "ऑन-चेन एनालिटिक्स से पता चलता है कि प्रमुख स्पॉट ईटीएफ में लगातार संस्थागत संचय हो रहा है क्योंकि नेटवर्क हैश रेट नए सर्वकालिक उच्च स्तर पर पहुंच गया है।",
    "Vulnerability Patch Applied: Market orders execute strictly at current asset price; limit orders are placed into pending orders book.": "सुरक्षा पैच लागू: मार्केट ऑर्डर वर्तमान एसेट मूल्य पर सख्ती से निष्पादित होते हैं; लिमिट ऑर्डर लंबित ऑर्डर बुक में रखे जाते हैं।",
    "• Tap the button below to open your mail client with pre-filled appeal details.\\n• Appeals are typically reviewed within 24–48 hours.": "• पहले से भरे हुए अपील विवरण के साथ अपने मेल क्लाइंट को खोलने के लिए नीचे दिए गए बटन पर टैप करें।\\n• अपीलों की समीक्षा आमतौर पर 24–48 घंटों के भीतर की जाती है।",
    "Enables 100% Free Push Notifications to closed & locked phones directly from this Admin Panel without Cloud Functions or credit cards.": "क्लाउड फंक्शन्स या क्रेडिट कार्ड के बिना सीधे इस एडमिन पैनल से बंद और लॉक किए गए फोन पर 100% मुफ़्त पुश नोटिफिकेशन सक्षम करता है।",
    "Perpetual DEXs and on-chain order books report record daily open interest with advanced cross-margin and automated liquidation engines.": "परपेचुअल डीईएक्स और ऑन-चेन ऑर्डर बुक्स उन्नत क्रॉस-मार्जिन और स्वचालित परिसमापन (लिक्विडेशन) इंजनों के साथ रिकॉर्ड दैनिक ओपन इंटरेस्ट दर्ज कर रहे हैं।",
    "Real-time automated scanning across all 70+ crypto assets. Get instant confluence signals, recommended leverage, and entry/exit targets.": "सभी 70+ क्रिप्टो संपत्तियों में रीयल-टाइम स्वचालित स्कैनिंग। तुरंत संगम (कन्फ्लुएंस) सिग्नल, अनुशंसित लीवरेज और प्रवेश/निकास लक्ष्य प्राप्त करें।",
    "Enables 100% Free Push Notifications to closed & locked phones directly from this Admin Panel without Cloud Functions or credit cards.\\n\\n": "क्लाउड फ़ंक्शंस या क्रेडिट कार्ड के बिना सीधे इस एडमिन पैनल से बंद और लॉक किए गए फोन पर 100% निःशुल्क पुश सूचनाएं सक्षम करता है।\\n\\n",
    "Are you sure you want to permanently delete your account? All your stats, balances, and history will be lost. This action cannot be undone.": "क्या आप वाकई अपना खाता स्थायी रूप से हटाना चाहते हैं? आपके सभी आंकड़े, बैलेंस और इतिहास मिट जाएंगे। यह क्रिया पूर्ववत नहीं की जा सकती।",
    "• Instant Winner Claim: All Top 10 winners receive an in-app celebration popup on app open to claim virtual cash into their wallet balance.": "• तत्काल विजेता दावा: सभी शीर्ष 10 विजेताओं को अपने वॉलेट बैलेंस में वर्चुअल कैश का दावा करने के लिए ऐप खोलने पर इन-ऐप सेलिब्रेशन पॉपअप प्राप्त होता है।",
    "⚡ Qualification Rule: Only traders who crossed >0.0% profit qualify for payouts. Traders with 0.0% or negative scores are strictly excluded.": "⚡ योग्यता नियम: केवल वे ट्रेडर जिन्होंने >0.0% लाभ अर्जित किया है, वे भुगतान के लिए पात्र हैं। 0.0% या नकारात्मक स्कोर वाले ट्रेडर्स को पूरी तरह से बाहर रखा गया है।",
    "2. The client immediately opened an active futures position at that distorted price instead of queuing a pending order to await market trigger.": "2. क्लाइंट ने मार्केट ट्रिगर की प्रतीक्षा करने के लिए पेंडिंग ऑर्डर को कतार में रखने के बजाय उस विकृत मूल्य पर तुरंत एक सक्रिय फ्यूचर्स पोजीशन खोल दी।",
    "High volatility detected across BTC and major altcoins! Strengthen your margin buffer to survive unexpected market dips and ride the next rally.": "BTC और प्रमुख altcoins में उच्च अस्थिरता का पता चला! अप्रत्याशित बाज़ार गिरावट से बचने और अगली रैली का लाभ उठाने के लिए अपने मार्जिन बफर को मजबूत करें।",
    "Move markets like an institutional whale! Top up your virtual account to trade the deepest order books with maximum position sizing and zero fear.": "संस्थागत व्हेल की तरह मार्केट को हिलाएं! अधिकतम पोजीशन साइज़ और बिना किसी डर के सबसे गहरे ऑर्डर बुक्स में ट्रेड करने के लिए अपना वर्चुअल खाता टॉप अप करें।",
    "The portfolio and financial ledger failed mathematical verification. Evidence of unauthorized state manipulation or bug exploitation was detected.": "पोर्टफ़ोलियो और वित्तीय लेजर गणितीय सत्यापन में विफल रहे। अनधिकृत स्थिति हेरफेर या बग के दुरुपयोग का साक्ष्य मिला है।",
    "Crypto never sleeps! Top up your paper trading funds this weekend to unlock exclusive bonus balance and test high-leverage 20x strategies risk-free.": "क्रिप्टो कभी सोता नहीं है! विशेष बोनस बैलेंस अनलॉक करने और 20x उच्च-लीवरेज रणनीतियों का जोखिम-मुक्त परीक्षण करने के लिए इस सप्ताहांत अपने पेपर ट्रेडिंग फंड को टॉप-अप करें।",
    "To use biometric unlock, your device must support biometric sensors and have at least one fingerprint or face enrolled in Android Settings -> Security.": "बायोमेट्रिक अनलॉक का उपयोग करने के लिए, आपके डिवाइस में बायोमेट्रिक सेंसर होना चाहिए और एंड्रॉइड सेटिंग्स -> सुरक्षा में कम से कम एक फिंगरप्रिंट या चेहरा पंजीकृत होना चाहिए।",
    "By entering, you acknowledge that this is a paper-trading simulator for educational purposes. No real money is traded, and this app does not provide financial advice.": "प्रवेश करके, आप स्वीकार करते हैं कि यह शैक्षणिक उद्देश्यों के लिए एक पेपर-ट्रेडिंग सिम्युलेटर है। कोई वास्तविक धन ट्रेड नहीं किया जाता है, और यह ऐप वित्तीय सलाह प्रदान नहीं करता है।",
    "The weekly leaderboard race is heating up! Secure extra virtual margin now to execute calculated high-ROE trades and climb into the Top 10 prize zone before Sunday midnight.": "साप्ताहिक लीडरबोर्ड की दौड़ तेज़ हो रही है! नपे-तुले उच्च-ROE ट्रेड करने और रविवार आधी रात से पहले टॉप 10 पुरस्कार क्षेत्र में पहुंचने के लिए अतिरिक्त वर्चुअल मार्जिन सुरक्षित करें।",
    "Market volatility is going crazy right now! Don't let your positions get liquidated. Top up your virtual war chest today and get up to 50% extra bonus trading power instantly.": "मार्केट की अस्थिरता इस समय चरम पर है! अपनी पोजीशन को लिक्विडेट न होने दें। आज ही अपने वर्चुअल फंड को टॉप अप करें और तुरंत 50% तक अतिरिक्त बोनस ट्रेडिंग पावर पाएं।",
    "We reserve the right to update or modify these Terms & Conditions at any time. Continued use of PaperTrading - Crypto & Stocks following any updates constitutes full acceptance of the revised terms.": "हम किसी भी समय इन नियमों और शर्तों को अपडेट या संशोधित करने का अधिकार सुरक्षित रखते हैं। किसी भी अपडेट के बाद PaperTrading - Crypto & Stocks का निरंतर उपयोग संशोधित शर्तों की पूर्ण स्वीकृति माना जाएगा।",
    "Your privacy is essential to us. Please review our comprehensive Privacy Policy for full details on how account information, anonymous diagnostic metrics, and simulation states are safeguarded.": "आपकी गोपनीयता हमारे लिए महत्वपूर्ण है। खाता जानकारी, अज्ञात नैदानिक मेट्रिक्स और सिमुलेशन स्थिति को कैसे सुरक्षित रखा जाता है, इसके पूर्ण विवरण के लिए कृपया हमारी व्यापक गोपनीयता नीति की समीक्षा करें।",
    "• Swipe horizontally along the Milestone Road to preview and claim capital grants as you rank up.\\n• Check in daily to maintain your streak.\\n• Complete trading quests to accelerate XP progression.": "• रैंक बढ़ने पर पूंजी अनुदान देखने और दावा करने के लिए माइलस्टोन रोड पर क्षैतिज रूप से स्वाइप करें।\\n• अपनी स्ट्रीक बनाए रखने के लिए रोजाना चेक-इन करें।\\n• XP प्रगति को तेज करने के लिए ट्रेडिंग क्वेस्ट पूरे करें।",
    "• Positive Profit Requirement (>0.0%): Traders must cross 0.0% profit (>0.0%) to qualify for prize payouts. Participants with 0.0% or negative scores will not receive prize money even if placed in the Top 10.": "• सकारात्मक लाभ की आवश्यकता (>0.0%): पुरस्कार भुगतान के लिए योग्य होने हेतु ट्रेडर्स को 0.0% से अधिक लाभ (>0.0%) प्राप्त करना होगा। 0.0% या नकारात्मक स्कोर वाले प्रतिभागियों को शीर्ष 10 में स्थान पाने पर भी पुरस्कार राशि नहीं मिलेगी।",
    "Many traders get lucky with 100x leverage and win huge multipliers. This is NOT considered cheating as long as:\\n• Margin was legitimately deducted from their balance.\\n• Leverage stayed <= 100x.\\n• Price action and PnL adhere to the mathematical formula.\\n• The position did not survive past liquidation price.": "कई ट्रेडर्स 100x लीवरेज के साथ भाग्यशाली होते हैं और भारी मल्टीप्लायर जीतते हैं। इसे तब तक धोखाधड़ी नहीं माना जाता जब तक कि:\\n• उनके बैलेंस से मार्जिन वैध रूप से काटा गया हो।\\n• लीवरेज <= 100x बना रहा हो।\\n• प्राइस एक्शन और PnL गणितीय फॉर्मूले का पालन करते हों।\\n• पोजीशन लिक्विडेशन मूल्य से आगे नहीं टिकी रही हो।",
    "Educational & CFTC Rule 4.41 Notice: All algorithmic signals, indicators, and leverage models are generated mathematically for educational paper-trading simulation purposes only. PaperTrading - Crypto & Stocks is NOT a registered investment advisor, commodity trading advisor, or broker. This does not constitute financial, legal, or investment advice. Simulated results have inherent limitations, are prepared with the benefit of hindsight, and do not guarantee real-world trading performance.": "शैक्षणिक और CFTC नियम 4.41 सूचना: सभी एल्गोरिदमिक सिग्नल, संकेतक और लीवरेज मॉडल विशुद्ध रूप से शैक्षणिक पेपर-ट्रेडिंग सिमुलेशन उद्देश्यों के लिए गणितीय रूप से उत्पन्न होते हैं। PaperTrading - Crypto & Stocks एक पंजीकृत निवेश सलाहकार, कमोडिटी ट्रेडिंग सलाहकार या ब्रोकर नहीं है। यह वित्तीय, कानूनी या निवेश सलाह का गठन नहीं करता है। सिम्युलेटेड परिणामों की अंतर्निहित सीमाएं होती हैं, वे पूर्वव्यापी प्रभाव से तैयार किए जाते हैं, और वास्तविक दुनिया के व्यापार प्रदर्शन की गारंटी नहीं देते हैं।",
  };

