    "Placed limit and stop-limit orders waiting for market trigger will appear here.": "Las órdenes límite y stop-límite colocadas a la espera del activador de mercado aparecerán aquí.",
    "Stacks is a Layer 2 for Bitcoin, enabling smart contracts and dApps on Bitcoin.": "Stacks es una Capa 2 para Bitcoin que permite contratos inteligentes y dApps en Bitcoin.",
    "No account found with this email address. Please check your spelling or sign up.": "No se encontró ninguna cuenta con este correo electrónico. Por favor, revisa la ortografía o regístrate.",
    "Set up your trader identity and preferences to begin simulated market execution.": "Configura tu identidad de trader y preferencias para comenzar la operativa simulada.",
    "Solvency verified: User never went negative during their entire trading history.": "Solvencia verificada: el usuario nunca tuvo saldo negativo durante todo su historial de trading.",
    "Arbitrum is a leading Ethereum Layer 2 scaling solution using optimistic rollups.": "Arbitrum es una solución líder de escalado de Capa 2 de Ethereum que utiliza rollups optimistas.",
    "Could not fetch recent price history. Please check your connection and try again.": "No se pudo obtener el historial de precios reciente. Por favor verifica tu conexión e inténtalo de nuevo.",
    "Curve is a decentralized exchange optimized for stablecoin trading with low fees.": "Curve es un exchange descentralizado optimizado para el trading de stablecoins con comisiones bajas.",
    "Bitcoin Cash is a fork of Bitcoin with larger block sizes for faster transactions.": "Bitcoin Cash es una bifurcación de Bitcoin con bloques más grandes para transacciones más rápidas.",
    "Bonk is the first dog-themed social utility token launched on the Solana ecosystem.": "Bonk es el primer token de utilidad social con temática de perro lanzado en el ecosistema de Solana.",
    "Market candle data is slow to respond or unavailable. Please check your connection.": "Los datos de velas del mercado tardan en responder o no están disponibles. Por favor, verifica tu conexión.",
    "Check in daily in the Rewards tab to maintain your streak flame and climb the ranks!": "¡Regístrate diariamente en la pestaña de Recompensas para mantener la llama de tu racha y subir de rango!",
    "Ethereum Classic is the original, immutable proof-of-work smart contract blockchain.": "Ethereum Classic es la cadena de bloques de contratos inteligentes de prueba de trabajo original e inmutable.",
    "Maintain daily check-in habits. Complete Day 7 to unlock the legendary streak vault.": "Mantén el hábito de check-in diario. Completa el Día 7 para desbloquear la bóveda de racha legendaria.",
    "No fingerprints or face enrolled on device. Please register one in Android Settings.": "No hay huellas dactilares ni rostro registrados en el dispositivo. Registra uno en los ajustes de Android.",
    "Please log out and log back in to verify your identity before deleting your account.": "Por favor, cierra sesión y vuelve a iniciar sesión para verificar tu identidad antes de eliminar tu cuenta.",
    "Zero-margin futures exploit: Opened high-leverage position without margin deduction.": "Vulnerabilidad de futuros sin margen: se abrió posición con alto apalancamiento sin deducir margen.",
    "BOOK OF MEME is an experimental Web3 meme creation and decentralized storage project.": "BOOK OF MEME es un proyecto experimental de creación de memes Web3 y almacenamiento descentralizado.",
    "Decentraland is a virtual world where users can buy, sell, and build on virtual land.": "Decentraland es un mundo virtual donde los usuarios pueden comprar, vender y construir sobre terrenos virtuales.",
    "Password must be at least 8 characters and include uppercase, lowercase, and numbers.": "La contraseña debe tener al menos 8 caracteres e incluir mayúsculas, minúsculas y números.",
    "ROI measures the profitability of an investment as a percentage of the original cost.": "El ROI mide la rentabilidad de una inversión como un porcentaje del coste original.",
    "User cash balance remained solvent throughout all sequential trades and transactions.": "El saldo en efectivo del usuario se mantuvo solvente en todas las operaciones y transacciones sucesivas.",
    "Broadcast instant notifications to all active paper traders or target a specific user.": "Difunde notificaciones instantáneas a todos los traders simulados activos o apunta a un usuario específico.",
    "Sui is a Layer 1 blockchain and smart contract platform designed for instant finality.": "Sui es una blockchain de Capa 1 y plataforma de contratos inteligentes diseñada para finalidad instantánea.",
    "XRP is the native asset of the XRP Ledger, used for fast and low-cost global payments.": "XRP es el activo nativo del XRP Ledger, utilizado para pagos globales rápidos y de bajo costo.",
    "Bitcoin is the first decentralized cryptocurrency, created by Satoshi Nakamoto in 2009.": "Bitcoin es la primera criptomoneda descentralizada, creada por Satoshi Nakamoto en 2009.",
    "Cardano is a proof-of-stake blockchain platform focused on security and sustainability.": "Cardano es una plataforma blockchain de prueba de participación centrada en la seguridad y la sostenibilidad.",
    "Maker is the governance token of the MakerDAO protocol, which issues the DAI stablecoin.": "Maker es el token de gobernanza del protocolo MakerDAO, que emite la stablecoin DAI.",
    "Chainlink is a decentralized oracle network providing real-world data to smart contracts.": "Chainlink es una red de oráculos descentralizada que proporciona datos del mundo real a los contratos inteligentes.",
    "Every coin held in the portfolio matches historical buy orders minus sell orders exactly.": "Cada moneda mantenida en el portafolio coincide exactamente con las órdenes históricas de compra menos las órdenes de venta.",
    "Solana is a high-performance blockchain supporting fast, low-cost transactions and dApps.": "Solana es una blockchain de alto rendimiento que admite transacciones rápidas y de bajo coste, además de dApps.",
    "Add funds to your paper trading account to practice new strategies without financial risk.": "Añade fondos a tu cuenta de paper trading para practicar nuevas estrategias sin riesgo financiero.",
    "Aptos is a Layer 1 blockchain built on Move language, focused on safety and upgradability.": "Aptos es una blockchain de Capa 1 construida en el lenguaje Move, centrada en la seguridad y la capacidad de actualización.",
    "Reconciling ledger, auditing holdings vs trade history, verifying 100x leverage margins...": "Conciliando el libro mayor, auditando tenencias vs historial de trades, verificando márgenes de apalancamiento de 100x...",
    "XP tracks your real-time trading experience across Spot, Futures Pro, and 1v1 Blitz duels.": "La XP registra tu experiencia de trading en tiempo real en Spot, Futuros Pro y duelos Blitz 1v1.",
    "Your available cash is empty. Watch a short video to claim an instant free capital refill.": "Tu efectivo disponible está agotado. Mira un video corto para reclamar una recarga gratuita al instante.",
    "Dogecoin started as a meme but grew into one of the largest cryptocurrencies by market cap.": "Dogecoin comenzó como un meme pero se convirtió en una de las mayores criptomonedas por capitalización de mercado.",
    "Enter the email associated with your account and we will send you a password recovery link.": "Ingresa el correo electrónico asociado a tu cuenta y te enviaremos un enlace de recuperación de contraseña.",
    "Jito is a liquid staking protocol and MEV infrastructure platform for the Solana ecosystem.": "Jito es un protocolo de liquid staking y plataforma de infraestructura MEV para el ecosistema Solana.",
    "Zombie position exploit: Active position breached liquidation price but was not liquidated.": "Vulnerabilidad de posición zombi: la posición activa superó el precio de liquidación pero no fue liquidada.",
    "dogwifhat is a popular decentralized community meme coin launched on the Solana blockchain.": "dogwifhat es una popular moneda meme comunitaria descentralizada lanzada en la blockchain de Solana.",
    "Filecoin is a decentralized storage network to store the world's most important information.": "Filecoin es una red de almacenamiento descentralizada para guardar la información más importante del mundo.",
    "Notcoin is a viral Web3 tap-to-earn game and community token launched on the TON blockchain.": "Notcoin es un juego viral tap-to-earn de Web3 y token comunitario lanzado en la blockchain TON.",
    "Note: Please attach any screenshots or images directly to this email to help us investigate.": "Nota: Adjunta capturas de pantalla o imágenes directamente a este correo para ayudarnos a investigar.",
    "Notice: Your 10-day appeal window has expired. Permanent account deletion is being executed.": "Aviso: Tu período de apelación de 10 días ha expirado. Se está ejecutando la eliminación permanente de la cuenta.",
    "Pepe is a deflationary memecoin launched on Ethereum as a tribute to the Pepe the Frog meme.": "Pepe es una memecoin deflacionaria lanzada en Ethereum como tributo al meme de Pepe the Frog.",
    "Pyth Network is a high-frequency financial oracle network delivering sub-second market data.": "Pyth Network es una red de oráculos financieros de alta frecuencia que entrega datos de mercado en subsegundos.",
    "Are you sure you want to permanently delete this top-up record? This action cannot be undone.": "¿Estás seguro de que deseas eliminar permanentemente este registro de recarga? Esta acción no se puede deshacer.",
    "ZKsync is a Layer 2 scaling protocol using zero-knowledge rollups to scale Ethereum securely.": "ZKsync es un protocolo de escalado de Capa 2 que utiliza rollups de conocimiento cero para escalar Ethereum de forma segura.",
    "A wallet address is like a bank account number that others can use to send you cryptocurrency.": "Una dirección de billetera es como un número de cuenta bancaria que otros pueden usar para enviarte criptomonedas.",
    "Their posts and comments will no longer appear in your feed. You can unblock them at any time.": "Sus publicaciones y comentarios ya no aparecerán en tu feed. Puedes desbloquearlos en cualquier momento.",
    "Welcome to the new trading season! Compete in the Weekly Championship for virtual cash prizes.": "¡Bienvenido a la nueva temporada de trading! Compite en el Campeonato Semanal por premios virtuales en efectivo.",
    "Could not connect to your account profile. Please check your internet connection and try again.": "No se pudo conectar a tu perfil de cuenta. Por favor verifica tu conexión a internet e inténtalo de nuevo.",
    "Describe the feature in detail. The more context you give, the easier it is for us to build it.": "Describe la función en detalle. Cuanto más contexto proporciones, más fácil será para nosotros crearla.",
    "Ethereum is a decentralized platform for smart contracts and dApps, created by Vitalik Buterin.": "Ethereum es una plataforma descentralizada para contratos inteligentes y dApps, creada por Vitalik Buterin.",
    "Avalanche is a smart contract platform designed for DeFi with near-instant transaction finality.": "Avalanche es una plataforma de contratos inteligentes diseñada para DeFi con finalidad de transacción casi instantánea.",
    "Enable a 4-digit PIN and Biometric Lock to keep your virtual trading portfolio and stats secure.": "Habilita un PIN de 4 dígitos y bloqueo biométrico para mantener seguros tu cartera de trading virtual y tus estadísticas.",
    "Ban this user account or apply an administrative reset to protect the competition and leaderboard.": "Suspende esta cuenta de usuario o aplica un restablecimiento administrativo para proteger la competencia y la tabla de clasificación.",
    "Current market price has breached the position liquidation threshold, but position remains active.": "El precio de mercado actual ha superado el umbral de liquidación de la posición, pero la posición permanece activa.",
    "Inspect ideas, feature suggestions, and UX improvements submitted by traders across the community.": "Inspecciona ideas, sugerencias de funciones y mejoras de UX enviadas por traders de la comunidad.",
    "Stellar is an open blockchain network connecting financial institutions for low-cost transactions.": "Stellar es una red blockchain abierta que conecta instituciones financieras para transacciones de bajo costo.",
    "Account verification is taking longer than expected. Please check your network or proceed to login.": "La verificación de la cuenta está tardando más de lo previsto. Comprueba tu red o continúa iniciando sesión.",
    "Verifying all spot trades, futures margin deductions,\\ncoin inventory, and ledger reconciliation...": "Verificando todas las operaciones spot, deducciones de margen de futuros,\\ninventario de monedas y conciliación contable...",
    "A limit order guarantees the price but not the execution, as the market must reach your limit price.": "Una orden límite garantiza el precio pero no la ejecución, ya que el mercado debe alcanzar tu precio límite.",
    "Arkham is an AI-powered blockchain analysis and intelligence platform revealing transaction origins.": "Arkham es una plataforma de análisis e inteligencia de blockchain impulsada por IA que revela los orígenes de las transacciones.",
    "Celestia is a modular blockchain network that rethinks data availability and consensus architecture.": "Celestia es una red blockchain modular que replantea la disponibilidad de datos y la arquitectura de consenso.",
    "Fantom is a highly scalable blockchain platform for DeFi, crypto dApps, and enterprise applications.": "Fantom es una plataforma blockchain altamente escalable para DeFi, dApps cripto y aplicaciones empresariales.",
    "Illegal leverage detected: User has futures positions with leverage exceeding the 100x platform cap.": "Apalancamiento ilegal detectado: el usuario tiene posiciones de futuros con apalancamiento que supera el límite de 100x de la plataforma.",
    "Cross-checks every coin in the user portfolio against their historical buy and sell trades. Flags any": "Verifica cada moneda en la cartera del usuario frente a su historial de compras y ventas. Marca cualquier",
    "Explore markets, test your trading strategies with zero risk, and compete in the Weekly Championship!": "¡Explora los mercados, prueba tus estrategias de trading sin riesgo y compite en el Campeonato Semanal!",
    "From trade fills and liquidation alerts to weekly championship prizes, your alerts will show up here.": "Desde ejecuciones de órdenes y alertas de liquidación hasta premios del campeonato semanal, tus alertas aparecerán aquí.",
    "Going long means you are buying a contract with the expectation that the asset's price will increase.": "Ir en largo significa que compras un contrato con la expectativa de que el precio del activo aumente.",
    "Pendle is a permissionless yield-trading protocol enabling tokenization and trading of future yields.": "Pendle es un protocolo de negociación de rendimiento sin permisos que permite la tokenización y el comercio de rendimientos futuros.",
    "Review trade and wallet history manually. Ban is NOT recommended unless suspicious patterns escalate.": "Revisa el historial de operaciones y billetera manualmente. NO se recomienda suspender a menos que los patrones sospechosos aumenten.",
    "Watch a short video to receive an instant free capital refill and jump straight back into the market.": "Mira un video corto para recibir una recarga de capital gratis al instante y regresar al mercado.",
    "Hardware wallets keep your private keys offline, protecting your assets from online hacks and malware.": "Las billeteras de hardware mantienen tus claves privadas fuera de línea, protegiendo tus activos de hackeos y malware.",
    "Toncoin is the decentralized Layer 1 blockchain developed by Telegram for scalable micro-transactions.": "Toncoin es la blockchain descentralizada de Capa 1 desarrollada por Telegram para microtransacciones escalables.",
    "VeChain is an enterprise blockchain platform enhancing supply chain management and business processes.": "VeChain es una plataforma blockchain empresarial que mejora la gestión de la cadena de suministro y procesos de negocio.",
    "io.net is a decentralized physical infrastructure network providing on-demand distributed GPU compute.": "io.net es una red de infraestructura física descentralizada que proporciona computación de GPU distribuida bajo demanda.",
    "• 1v1 Blitz Arena Boost: Every blitz arena win awards +5.0% score directly to your championship tally.": "• Impulso Arena Blitz 1v1: Cada victoria en la arena blitz otorga +5.0% de puntuación directamente a tu marcador del campeonato.",
    "A stop-loss order helps manage risk by automatically closing a position if the price moves against you.": "Una orden stop-loss ayuda a gestionar el riesgo cerrando automáticamente una posición si el precio se mueve en tu contra.",
    "Chiliz powers Socios.com, enabling fans to purchase Fan Tokens for top football clubs and sports teams.": "Chiliz impulsa Socios.com, lo que permite a los aficionados comprar Fan Tokens para los mejores clubes y equipos deportivos.",
    "Ethena is a synthetic dollar protocol built on Ethereum that provides crypto-native yield through USDe.": "Ethena es un protocolo de dólar sintético creado en Ethereum que proporciona rendimiento nativo de criptomonedas a través de USDe.",
    "1. User executed orders exceeding available virtual cash, plunging balance into deep negative overdraft.": "1. El usuario ejecutó órdenes que superaban el efectivo virtual disponible, hundiendo el saldo en un profundo sobregiro negativo.",
    "Algorand is a self-sustaining, decentralized blockchain network supporting a wide range of applications.": "Algorand es una red blockchain descentralizada y autosuficiente que admite una amplia variedad de aplicaciones.",
    "Market structure is bullish. Enter on minor dips towards support with targets set at recent swing highs.": "La estructura del mercado es alcista. Entra en retrocesos leves hacia el soporte con objetivos en los máximos recientes.",
    "Price is consolidating in a neutral band. Wait for a definitive breakout above resistance before buying.": "El precio se está consolidando en una banda neutral. Espera a una ruptura definitiva por encima de la resistencia antes de comprar.",
    "Upward momentum waning near resistance. Consider trimming profits or placing tight trailing stop-losses.": "El impulso alcista se debilita cerca de la resistencia. Considera tomar ganancias o colocar trailing stops ajustados.",
    "Sei is the fastest Layer 1 blockchain, specialized for trading and decentralized exchange infrastructure.": "Sei es la blockchain de capa 1 más rápida, especializada en trading e infraestructura de intercambios descentralizados.",
    "Track real monetary revenue, Google Play purchase tokens, approval statuses, and user payment timestamps.": "Rastrea ingresos monetarios reales, tokens de compra de Google Play, estados de aprobación y marcas de tiempo de pago.",
    "Welcome to the new trading season! Enjoy smoother charts, upgraded indicators, and enhanced server speed.": "¡Bienvenido a la nueva temporada de trading! Disfruta de gráficos más fluidos, indicadores mejorados y mayor velocidad de servidor.",
    "1. User virtual balance was directly altered in Firestore without matching trade profits or daily rewards.": "1. El saldo virtual del usuario fue alterado directamente en Firestore sin coincidir con ganancias de trading ni recompensas diarias.",
    "• Weekly Fresh Start: Leaderboard scores reset to 0.0% every week so all traders compete on equal footing.": "• Reinicio semanal: Las puntuaciones de la clasificación se reinician al 0.0% cada semana para que todos los traders compitan en igualdad de condiciones.",
    "Market Cap is calculated by multiplying the current price of a single coin by its total circulating supply.": "La capitalización de mercado se calcula multiplicando el precio actual de una moneda por su suministro circulante total.",
    "Starknet is a Permissionless Validity-Rollup Layer 2 for Ethereum scaling using STARK cryptographic proofs.": "Starknet es una Capa 2 Validity-Rollup sin permisos para escalar Ethereum usando pruebas criptográficas STARK.",
    "All winners receive an in-app claim popup. Tournament scores will be safely reset to 0.0% for the next week.": "Todos los ganadores reciben un aviso de reclamación en la app. Las puntuaciones del torneo se restablecerán de forma segura al 0.0% para la próxima semana.",
    "GMX is a decentralized spot and perpetual exchange that supports low swap fees and zero price impact trades.": "GMX es un exchange descentralizado de spot y perpetuos que admite comisiones bajas y operaciones sin impacto en el precio.",
    "Severe bearish pressure and moving average breakdown. Recommended to sell spot holdings or preserve capital.": "Fuerte presión bajista y ruptura de medias móviles. Se recomienda vender tenencias spot o preservar el capital.",
    "Crypto never sleeps! Trade the weekend volatility with up to 20x leverage on BTC, ETH, and trending altcoins.": "¡El mercado cripto nunca duerme! Opera la volatilidad del fin de semana con hasta 20x de apalancamiento en BTC, ETH y altcoins en tendencia.",
    "Standard volatility range. 10x leverage offers disciplined growth with an approximate 10% liquidation buffer.": "Rango de volatilidad estándar. El apalancamiento 10x ofrece un crecimiento disciplinado con un colchón de liquidación de aprox. 10%.",
    "The AI Signals Desk just published fresh Spot & Futures recommendations with clear Entry, TP, and SL targets.": "La mesa de señales de IA acaba de publicar nuevas recomendaciones de Spot y Futuros con objetivos claros de entrada, TP y SL.",
    "You will no longer see posts or comments from this trader on your timeline. You can unblock them at any time.": "Ya no verás publicaciones ni comentarios de este trader en tu cronología. Puedes desbloquearlo en cualquier momento.",
    "Unlock PaperTrading instantly using your Fingerprint or Face ID instead of typing your 4-digit PIN every time.": "Desbloquea PaperTrading al instante usando tu huella o Face ID en lugar de escribir tu PIN de 4 dígitos cada vez.",
    "Welcome to the Ultimate Crypto Trading Simulator! Here is a breakdown of all the features and how to use them.": "¡Bienvenido al mejor simulador de trading cripto! Aquí tienes un desglose de todas las funciones y cómo utilizarlas.",
    "Auto-Payout Active: Every Monday at 12:00 AM midnight, top 10 traders are credited and tournament scores reset.": "Pago automático activo: Cada lunes a las 12:00 AM de la medianoche, se acreditan los 10 mejores traders y se reinician las puntuaciones del torneo.",
    "Traders are waiting in the Arena! Put your trading skills to the test in 60-second live blitz duels to earn XP.": "¡Los traders te esperan en la Arena! Pon a prueba tus habilidades de trading en duelos blitz en vivo de 60 segundos para ganar XP.",
    "1. User injected or synced coin holdings directly without corresponding buy trade transactions in trade history.": "1. El usuario inyectó o sincronizó tenencias de monedas directamente sin las transacciones de compra correspondientes en el historial de operaciones.",
    "Your daily activity reward has been unlocked! Check in now to maintain your streak and claim bonus virtual cash.": "¡Tu recompensa de actividad diaria ha sido desbloqueada! Regístrate ahora para mantener tu racha y reclamar efectivo virtual adicional.",
    "Your honest review helps other paper traders discover the app and supports our continuous simulator improvements.": "Tu reseña sincera ayuda a otros traders a descubrir la aplicación y respalda nuestras continuas mejoras al simulador.",
    "Moderate price swings. 5x leverage offers balanced amplification while keeping liquidation at a safe 20% distance.": "Oscilaciones de precios moderadas. El apalancamiento de 5x ofrece una amplificación equilibrada mientras mantiene la liquidación a una distancia segura del 20%.",
    "Ondo Finance is an institutional-grade protocol bridging traditional finance with decentralized blockchain assets.": "Ondo Finance es un protocolo de nivel institucional que une las finanzas tradicionales con los activos descentralizados en blockchain.",
    "Only a few hours left today! Claim your daily reward to multiply your virtual cash bonus and unlock streak badges.": "¡Solo quedan unas horas hoy! Reclama tu recompensa diaria para multiplicar tu bono de efectivo virtual y desbloquear insignias de racha.",
    "Bonus virtual cash has been credited to active traders! Test out fresh Spot and Futures strategies risk-free today.": "¡Se ha acreditado efectivo virtual de bonificación a los traders activos! Prueba hoy nuevas estrategias de Spot y Futuros sin riesgo.",
    "Internet Computer is a blockchain network that enables developers to build and host decentralized web applications.": "Internet Computer es una red blockchain que permite a los desarrolladores crear y alojar aplicaciones web descentralizadas.",
    "The weekly leaderboard finalizes at Sunday midnight! Enter high-conviction trades now to lock in your Top 10 prize.": "¡La tabla de clasificación semanal finaliza el domingo a medianoche! Ingresa operaciones de alta convicción ahora para asegurar tu premio del Top 10.",
    "Your trading account has been suspended by an administrator for violating community or trading platform guidelines.": "Tu cuenta de trading ha sido suspendida por un administrador por violar las directrices de la comunidad o de la plataforma.",
    "Daily rewards, check-ins, and quest milestones were claimed with proper intervals and legitimate streak progression.": "Las recompensas diarias, los check-ins y los hitos de misiones se reclamaron con intervalos correctos y una progresión legítima de la racha.",
    "No ad available right now. Google AdMob is currently warming up ad inventory for this app. Please try again shortly.": "No hay anuncios disponibles en este momento. Google AdMob está preparando el inventario para esta aplicación. Vuelve a intentarlo en breve.",
    "Qualification Rule: Must cross >0.0% profit to receive prize money. 0.0% or negative scores are strictly ineligible.": "Regla de clasificación: Debe superar el >0.0% de beneficio para recibir el premio. Los resultados de 0.0% o negativos son estrictamente no elegibles.",
    "Account displays minor numerical drift or rounding variance, but no definitive proof of cheating or bug exploitation.": "La cuenta muestra una ligera desviación numérica o variación de redondeo, pero ninguna prueba definitiva de trampas o explotación de errores.",
    "Crypto markets are experiencing high volume and breakout momentum. Review your open positions and manage stop-losses.": "Los mercados cripto están experimentando un alto volumen e impulso de ruptura. Revisa tus posiciones abiertas y gestiona tus stop-loss.",
    "Search any trader by UID to inspect their live spot portfolio, open futures leverage, and suspicious trading volumes.": "Busca a cualquier trader por UID para inspeccionar su portafolio spot en vivo, apalancamiento de futuros abierto y volúmenes de trading sospechosos.",
    "Interactive TradingView WebView is supported on Android, iOS & macOS.\\nSwitch to native chart view for other platforms.": "El WebView interactivo de TradingView es compatible con Android, iOS y macOS.\\nCambia a la vista de gráfico nativa para otras plataformas.",
    "Leverage lets you trade with more money than you actually have, amplifying both potential profits and potential losses.": "El apalancamiento te permite operar con más dinero del que realmente tienes, amplificando tanto las ganancias como las pérdidas potenciales.",
    "Limited time flash deal! Top up your virtual account today and receive up to 50% extra bonus capital for paper trading.": "¡Oferta flash por tiempo limitado! Recarga tu cuenta virtual hoy y recibe hasta un 50% de capital de bonificación adicional para paper trading.",
    "A new version of Acadrio Trade is available on Google Play Store. Update now for new features and performance improvements!": "¡Una nueva versión de Acadrio Trade está disponible en Google Play Store. ¡Actualiza ahora para nuevas funciones y mejoras de rendimiento!",
    "Search by Public UID (PT-XXXXXX), Firebase UID, or Email\\nto view real-time holdings, futures positions, and recent trades.": "Busca por UID público (PT-XXXXXX), UID de Firebase o correo electrónico\\npara ver tenencias en tiempo real, posiciones de futuros y operaciones recientes.",
    "• Zero Real-Money Risk: Prizes are virtual paper trading capital credited to your account for risk-free strategy execution.": "• Cero riesgo de dinero real: Los premios son capital virtual de paper trading acreditado en tu cuenta para ejecutar estrategias sin riesgo.",
    "Weekly Leaderboard settled! Top 3 traders have received their virtual capital prizes directly to their paper trading wallet.": "¡Tabla semanal finalizada! Los 3 mejores traders recibieron sus premios de capital virtual directamente en su billetera de paper trading.",
    "No ad inventory available right now. Google AdMob is currently warming up ad inventory for this app. Please try again shortly.": "No hay inventario de anuncios disponible en este momento. Google AdMob está preparando el inventario para esta aplicación. Vuelve a intentarlo en breve.",
    "Congratulations to the Top 10 traders! Cash awards have been credited. All players are reset to 0.0% baseline for the new week.": "¡Felicitaciones a los 10 mejores traders! Los premios en efectivo han sido acreditados. Todos los jugadores se restablecen a la base de 0.0% para la nueva semana.",
    "If you believe this suspension is a mistake or wish to appeal, you can submit an appeal directly via email to our support team.": "Si crees que esta suspensión es un error o deseas apelar, puedes enviar una apelación directamente por correo electrónico a nuestro equipo de soporte.",
