  };

static String tr(String text, [String? targetLang]) {
    final lang = targetLang ?? currentLanguage;
    if (lang == 'English' || lang == 'en') return text;

    final dict = (lang == 'Hindi' || lang == 'hi')
        ? _hi
        : ((lang == 'Spanish' || lang == 'es') ? _es : null);
    if (dict == null) return text;

    // 1. Direct match
    if (dict.containsKey(text)) return dict[text]!;

    // 2. Trimmed match (retaining spacing)
    final trimmed = text.trim();
    if (dict.containsKey(trimmed)) {
      final translated = dict[trimmed]!;
      final prefixLen = text.indexOf(trimmed);
      final leading = text.substring(0, prefixLen);
      final trailing = text.substring(prefixLen + trimmed.length);
      return '$leading$translated$trailing';
    }

    // 3. Uppercase match
    final upper = text.toUpperCase();
    if (dict.containsKey(upper)) return dict[upper]!;

    // 4. Prefix / Suffix dynamic patterns
    // e.g. "Streak: 5", "Win Rate: 60%", "Level: 3"
    final colonIdx = text.indexOf(':');
    if (colonIdx > 0 && colonIdx < text.length - 1) {
      final left = text.substring(0, colonIdx).trim();
      final right = text.substring(colonIdx + 1).trim();
      if (dict.containsKey(left)) {
        return '${dict[left]!}: $right';
      }
    }

    // e.g. "5 Days", "10 Wins", "12 Trades", "Rank #1", "Tier 2"
    final spaceIdx = text.indexOf(' ');
    if (spaceIdx > 0 && spaceIdx < text.length - 1) {
      final first = text.substring(0, spaceIdx).trim();
      final rest = text.substring(spaceIdx + 1).trim();
      // Case A: number / percentage + word (e.g., "5 Days", "58% Confidence")
      if (RegExp(r'^[\d\+%\-\$]+$').hasMatch(first) && dict.containsKey(rest)) {
        return '$first ${dict[rest]!}';
      }
      // Case B: word + number (e.g., "Rank #1" or "Level 2")
      if (dict.containsKey(first) && RegExp(r'^[#\d\+%\-\$]+$').hasMatch(rest)) {
        return '${dict[first]!} $rest';
      }
    }

    return text;
  }
}

/// Extension on [String] for effortless inline translations: `'Net Worth'.tr()`
extension AppStringTranslation on String {
  String tr([String? targetLanguage]) => AppTranslations.tr(this, targetLanguage);
}

/// Drop-in replacement for Flutter's [Text] widget that automatically localizes
/// its text content dynamically according to the user's selected language.
class Text extends StatelessWidget {
  final String? data;
  final InlineSpan? textSpan;
  final TextStyle? style;
  final StrutStyle? strutStyle;
  final TextAlign? textAlign;
  final TextDirection? textDirection;
  final Locale? locale;
  final bool? softWrap;
  final TextOverflow? overflow;
  final TextScaler? textScaler;
  final int? maxLines;
  final String? semanticsLabel;
  final TextWidthBasis? textWidthBasis;
  final TextHeightBehavior? textHeightBehavior;
  final Color? selectionColor;

  const Text(
    String this.data, {
    super.key,
    this.style,
    this.strutStyle,
    this.textAlign,
    this.textDirection,
    this.locale,
    this.softWrap,
    this.overflow,
    this.textScaler,
    this.maxLines,
    this.semanticsLabel,
    this.textWidthBasis,
    this.textHeightBehavior,
    this.selectionColor,
  }) : textSpan = null;

  const Text.rich(
    InlineSpan this.textSpan, {
    super.key,
    this.style,
    this.strutStyle,
    this.textAlign,
    this.textDirection,
    this.locale,
    this.softWrap,
    this.overflow,
    this.textScaler,
    this.maxLines,
    this.semanticsLabel,
    this.textWidthBasis,
    this.textHeightBehavior,
    this.selectionColor,
  }) : data = null;

  static InlineSpan _translateSpan(InlineSpan span, [String? targetLang]) {
    if (span is TextSpan) {
      return TextSpan(
        text: span.text != null ? AppTranslations.tr(span.text!, targetLang) : null,
        children: span.children?.map((c) => _translateSpan(c, targetLang)).toList(),
        style: span.style,
        recognizer: span.recognizer,
        mouseCursor: span.mouseCursor,
        onEnter: span.onEnter,
        onExit: span.onExit,
        semanticsLabel: span.semanticsLabel,
        locale: span.locale,
        spellOut: span.spellOut,
      );
    }
    return span;
  }

  @override
  Widget build(BuildContext context) {
    final activeLocale = Localizations.maybeLocaleOf(context);
    final targetLang = activeLocale?.languageCode;

    if (textSpan != null) {
      return m.Text.rich(
        _translateSpan(textSpan!, targetLang),
        key: key,
        style: style,
        strutStyle: strutStyle,
        textAlign: textAlign,
        textDirection: textDirection,
        locale: locale,
        softWrap: softWrap,
        overflow: overflow,
        textScaler: textScaler,
        maxLines: maxLines,
        semanticsLabel: semanticsLabel,
        textWidthBasis: textWidthBasis,
        textHeightBehavior: textHeightBehavior,
        selectionColor: selectionColor,
      );
    }
    return m.Text(
      AppTranslations.tr(data ?? '', targetLang),
      key: key,
      style: style,
      strutStyle: strutStyle,
      textAlign: textAlign,
      textDirection: textDirection,
      locale: locale,
      softWrap: softWrap,
      overflow: overflow,
      textScaler: textScaler,
      maxLines: maxLines,
      semanticsLabel: semanticsLabel,
      textWidthBasis: textWidthBasis,
      textHeightBehavior: textHeightBehavior,
      selectionColor: selectionColor,
    );
  }
}

typedef AppText = Text;
